[tikz]
\begin{tikzpicture}[scale=0.8,rotate=20]
\tikzset{tk/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (0pt,-4pt)--(0pt,4pt);}}}},tkk/.style={postaction={decorate,decoration={markings,mark=at position 0.5 with {\draw (-2.5pt,-4pt)--(-2.5pt,4pt);\draw (2.5pt,-4pt)--(2.5pt,4pt);}}}}}
\draw[tk] (0,0)--(4,0);
\draw[tkk] (4,0)--(4,2.5);
\draw[tk] (4,2.5)--(0,2.5);
\draw[tkk] (0,2.5)--(0,0);
\draw (0.3,0)--(0.3,0.3)--(0,0.3);
\draw (4,0.3)--(3.7,0.3)--(3.7,0);
\draw (3.7,2.5)--(3.7,2.2)--(4,2.2);
\draw (0,2.2)--(0.3,2.2)--(0.3,2.5);
\end{tikzpicture}
[/tikz]
Give the most specific name guaranteed by the marks.

[tikz]
\begin{tikzpicture}[scale=0.8]
\draw (-0.5,1.7)--(1.2,2.5)--(3.5,0.2)--(0,0)--cycle;
\node[left] at (-0.5,1.7) {$Q$};
\node[above] at (1.2,2.5) {$R$};
\node[right] at (3.5,0.2) {$P$};
\node[below left] at (0,0) {$S$};
\end{tikzpicture}
[/tikz]
Write a name for this quadrilateral starting at $P$ and going clockwise.
